#include <iiGUI/iiGUI.h>
#include <algorithm>
#include <iostream>
#include <stdexcept>
using namespace ii;
namespace {
void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
template<class T>T take(core::Result<T> r){if(!r)throw std::runtime_error(r.error().message);return std::move(*r);}
void good(core::Result<void> r){if(!r){if(r.error().cause)std::rethrow_exception(r.error().cause);throw std::runtime_error(r.error().message);}}
gui::CanvasFrame frame(){gui::CanvasFrame f{.viewport={0,0,512,256},.background={0,0,0,1}};f.panels.push_back({{256,0,256,256},{1,1,1,1},{1,1,1,1},0});auto& red=f.overlays.emplace_back();red.panels.push_back({{0,0,512,256},{1,0,0,1},{1,0,0,1},0});auto& glass=f.overlays.emplace_back();glass.backdrop=gui::BackdropMaterial{.bounds={80,40,352,176},.radius=28,.blur_radius=28};return f;}
void validation(){auto f=frame();check(gui::valid_canvas(f),"Valid GPU material rejected");f.overlays.back().backdrop->blur_radius=65;check(!gui::valid_canvas(f),"Unbounded blur admitted");f=frame();f.overlays.back().backdrop->tint.alpha=2;check(!gui::valid_canvas(f),"Invalid material color admitted");}
void pixels(){gui::Host host({.size={512,256},.minimum_size={320,220}});good(host.run({.opened=[&]{auto f=frame();good(host.set_canvas(f));auto a=take(host.capture_canvas());auto scale=take(host.snapshot()).backing_scale;auto pixel=[&](const gui::PixelBuffer& im,double x,double y){return &im.rgba[(std::size_t(y*scale)*im.width+std::size_t(x*scale))*4];};auto gray=pixel(a,254,128),corner=pixel(a,81,41);check(gray[0]>40&&gray[0]<245&&std::abs(int(gray[0])-gray[1])<3&&std::abs(int(gray[1])-gray[2])<3,"GPU blur did not sample base contents in linear light");check(corner[0]>245&&corner[1]<5,"Rounded material leaked outside its mask");auto info=take(host.graphics_info());check(info.backdrop_supported&&info.backdrop_blurs==1&&info.backdrop_texture_bytes>0&&info.backdrop_texture_bytes<=64*1024*1024,"GPU material resources/counters invalid");good(host.set_canvas(f));take(host.capture_canvas());check(take(host.graphics_info()).backdrop_blurs==info.backdrop_blurs,"Identical frame reblurred");
    f.overlays.front().panels.front().top=f.overlays.front().panels.front().bottom={0,1,0,1};good(host.set_canvas(f));take(host.capture_canvas());check(take(host.graphics_info()).backdrop_blurs==info.backdrop_blurs,"Overlay-only change invalidated content blur");
    f.overlays.back().backdrop->source=gui::BackdropSource::previous_layers;f.overlays.back().backdrop->blur_radius=0;f.overlays.back().backdrop->tint={0,0,0,.5};good(host.set_canvas(f));auto b=take(host.capture_canvas());auto green=pixel(b,200,128);check(green[0]<5&&green[1]>170&&green[1]<200&&green[2]<5,"Non-glass material did not tint previous layers in linear light");
    f.overlays.clear();good(host.set_canvas(f));take(host.capture_canvas());check(take(host.graphics_info()).backdrop_texture_bytes==0,"Removed material retained working textures");good(host.request_close());}}));}
void vulkan(){gui::Host host;good(host.run({.opened=[&]{auto f=frame();f.renderer=gui::Renderer::vulkan;good(host.set_canvas(f));auto material=take(host.capture_canvas());check(take(host.graphics_info()).backdrop_supported,"Vulkan backdrop capability is missing");f.overlays.back().backdrop.reset();good(host.set_canvas(f));check(take(host.capture_canvas()).rgba!=material.rgba,"Vulkan ignored the backdrop");good(host.request_close());}}));}
}
int main(int argc,char** argv){try{std::string name=argc>1?argv[1]:"pixels";if(name=="pixels")pixels();else if(name=="validation")validation();else if(name=="vulkan")vulkan();else throw std::runtime_error("Unknown backdrop case");std::cout<<"BACKDROP_GPU_OK "<<name<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
